#!/usr/bin/env node
'use strict';

// Extract every aligned 4-byte word from the ELF binary as an unsigned
// 32-bit little-endian integer, keyed by virtual address.
//
// The binary is mapped "flat" at the classic ELF load base 0x400000:
//   file offset 0  -> address 0x400000
//   file offset 4  -> address 0x400004
//   ...
// so each aligned word at file offset i lives at address 0x400000 + i.

const fs = require('fs');

const BASE = 0x400000;
const WORD = 4;

const path = process.argv[2];
if (!path) {
  process.stderr.write('usage: node extract.js <binary>\n');
  process.exit(1);
}

const buf = fs.readFileSync(path);

const out = {};
// Only emit complete, aligned words. The file is word-aligned (size % 4 == 0),
// so every byte belongs to exactly one word; this still guards partial tails.
for (let off = 0; off + WORD <= buf.length; off += WORD) {
  const addr = BASE + off;
  // Read as unsigned 32-bit little-endian, keep result within uint32 range.
  const value = buf.readUInt32LE(off) >>> 0;
  out[addr] = value;
}

process.stdout.write(JSON.stringify(out) + '\n');

