# Exhaustive independent check: recompute every value with Python struct and
# compare to out.json. This proves the arithmetic of my extractor (not a spot check).
python3 -c "
import json, struct
data = open('/app/a.out','rb').read()
base = 0x400000
ref = {}
for i in range(0, len(data)-3, 4):
    ref[base+i] = struct.unpack('<I', data[i:i+4])[0]
got = {int(k): v for k,v in json.load(open('out.json')).items()}
assert len(ref)==len(got), (len(ref), len(got))
mismatch = 0
for k in ref:
    if k not in got:
        mismatch+=1; print('MISSING', hex(k)); 
    elif got[k]!=ref[k]:
        mismatch+=1; print('MISMATCH', hex(k), got[k], ref[k])
print('reference words (independent):', len(ref))
print('extractor words:', len(got))
print('mismatches:', mismatch)
print('100%% match:', mismatch==0 and set(ref)==set(got))
"
